from pathlib import Path
p=Path('app-core.js')
s=p.read_text()
old="4:'The agent compiles the requirement specification from the complete application-owned Stage 04 obligation manifest. That manifest already carries current User Job Input, accepted Stage 01 job definition and captured human/material obligations, and accepted Stage 03 research/candidate obligations. Do not attach, resend, reopen, summarize, or ask for the original Stage 01 intent file. Do not ask the human to repeat any project information already captured. If required upstream canonical data is incomplete, return to the deficient earlier stage; do not make the human retranscribe it.'"
new="4:'The application supplies the complete Stage 04 obligation manifest from the current User Job Input, accepted Stage 01 capture, and accepted Stage 03 research. No original Stage 01 intent file is required here. If required upstream canonical data is incomplete, this stage remains unavailable until the deficient earlier stage is completed.'"
assert old in s, 'Stage 4 operator text target missing'
s=s.replace(old,new,1)
old="${n===2?'<div class=\"notice\"><strong>Independent external sources only.</strong> Prefer primary/official controlling authority where it exists; otherwise use the most authoritative, reputable, direct evidence appropriate to the domain. Existing target and repository artifacts may be implementation evidence for an audit/repair job, but they cannot become independent source authority merely by existing.</div>':''}"
assert old in s, 'Stage 2 duplicate agent semantics target missing'
s=s.replace(old,"",1)
old='<div class="panel"><h2 class="section-title">Returned agent response</h2><p class="section-intro">Paste only the final strict JSON from ChatGPT after the conversation is complete. If ChatGPT is still asking you questions, answer them there instead of pasting that conversation here. Parse / validate preserves the raw response first, then validates it without changing canonical project records. If the final response declares returned files, attach only those exact returned files when this stage shows a returned-file control. Never reattach the original Stage 01 intent file; Stages 03 and 04 consume the canonical captured intent and upstream records embedded in their controlling prompts.</p>'
new='<div class="panel"><h2 class="section-title">Returned agent response</h2><p class="section-intro">${locked?\'No response belongs to this stage yet. Complete every prerequisite stage first; do not send a prompt or paste JSON for this stage.\':String(s.status||\'\').toUpperCase()===\'COMPLETE\'&&Number(n)<canonicalCurrentStage()?\'This historical stage is complete. No new response belongs here; follow the current next action instead of reusing this stage.\':\'Paste only the final strict JSON from ChatGPT after the conversation is complete. If ChatGPT is still asking you questions, answer them there instead of pasting that conversation here. Parse / validate preserves the raw response first, then validates it without changing canonical project records. If the final response declares returned files, attach only those exact returned files when this stage shows a returned-file control. Never reattach the original Stage 01 intent file; later stages consume the canonical captured project authority and upstream records embedded in their controlling prompts.\'}</p>'
assert old in s, 'Returned response operator text target missing'
s=s.replace(old,new,1)
p.write_text(s)
